// OLIVE BRANCH — care guide loader (guardian shell only). UNVERIFIED — not yet checked by CI's Flutter run.
//
// Reads the bundled guide JSON (assets/care_guides/, generated by tools/care-guides-convert.mjs) from an
// [AssetBundle]: offline, no network, ever. Every guide goes through the review gate in care_guide_gate.dart before it
// is returned, so a caller cannot get a guide that is not allowed to be shown. Any error (missing asset, bad JSON, a
// guide that does not match the schema) drops that guide: the loader fails closed and never throws at a screen.
import 'dart:convert';

import 'package:flutter/services.dart' show AssetBundle, rootBundle;

import 'care_guide_gate.dart';
import 'care_guide_models.dart';

const String kCareGuideAssetDir = 'assets/care_guides';

class RejectedGuide {
  const RejectedGuide(this.id, this.reason);
  final String id;
  final GateRefusal? reason; // null = unreadable or malformed
}

class CareGuideLibrary {
  const CareGuideLibrary({required this.guides, this.draftIds = const <String>{}, this.rejected = const <RejectedGuide>[]});

  static const CareGuideLibrary empty = CareGuideLibrary(guides: <CareGuide>[]);

  /// In library order. Everything here has passed the gate.
  final List<CareGuide> guides;

  /// Ids in [guides] that are previewed drafts (always empty in a release build).
  final Set<String> draftIds;

  /// What the gate refused, for tests and logs. Never rendered.
  final List<RejectedGuide> rejected;

  bool get isEmpty => guides.isEmpty;
  bool isDraft(CareGuide g) => draftIds.contains(g.id);

  CareGuide? byId(String id) {
    for (final CareGuide g in guides) {
      if (g.id == id) return g;
    }
    return null;
  }

  /// The who-to-call guide, the emergency guide, when it is available.
  CareGuide? get whoToCall => byId('who-to-call');
}

class CareGuideLoader {
  CareGuideLoader({AssetBundle? bundle, this.policy = const CareGuidePolicy()}) : _bundle = bundle ?? rootBundle;
  final AssetBundle _bundle;
  final CareGuidePolicy policy;

  Future<CareGuideLibrary> load() async {
    final List<String> ids;
    try {
      final Object? idx = jsonDecode(await _bundle.loadString('$kCareGuideAssetDir/index.json'));
      if (idx is! Map<String, Object?>) return CareGuideLibrary.empty;
      final Object? list = idx['guides'];
      if (list is! List<Object?>) return CareGuideLibrary.empty;
      ids = <String>[for (final Object? e in list) if (e is String && RegExp(r'^[a-z0-9-]+$').hasMatch(e)) e];
    } on Object {
      return CareGuideLibrary.empty;
    }

    final List<CareGuide> out = <CareGuide>[];
    final Set<String> drafts = <String>{};
    final List<RejectedGuide> rejected = <RejectedGuide>[];
    for (final String id in ids) {
      try {
        final Object? raw = jsonDecode(await _bundle.loadString('$kCareGuideAssetDir/$id.json'));
        if (raw is! Map<String, Object?>) {
          rejected.add(RejectedGuide(id, null));
          continue;
        }
        // Cheap early refusal: a draft is not even parsed unless the preview switch is on in a non-release build.
        if (raw['status'] != kStatusReviewed && !policy.showsDrafts) {
          rejected.add(RejectedGuide(id, raw['status'] == kStatusDraft ? GateRefusal.notReviewed : GateRefusal.unknownStatus));
          continue;
        }
        final CareGuide g = CareGuide.fromJson(raw);
        if (g.id != id) {
          rejected.add(RejectedGuide(id, null));
          continue;
        }
        final GateDecision d = decideGuide(g, policy);
        if (!d.allowed) {
          rejected.add(RejectedGuide(id, d.refusal));
          continue;
        }
        out.add(g);
        if (d.isDraft) drafts.add(g.id);
      } on Object {
        rejected.add(RejectedGuide(id, null));
      }
    }
    return CareGuideLibrary(guides: List<CareGuide>.unmodifiable(out), draftIds: Set<String>.unmodifiable(drafts), rejected: rejected);
  }
}
